import numpy as np


def conv1d_valid(x, k):
    x = np.asarray(x, dtype=float)
    k = np.asarray(k, dtype=float)[::-1]
    n, m = len(x), len(k)
    return np.array([x[t:t + m] @ k for t in range(n - m + 1)])

